// Reproducer: FPFMAD (double precision) fused multiply-add conformance.
//
// Generated by verification/gen-fpfmad-directed.py from the reference model in
// verification/fma_reference.py: every expected value and flag below is that
// model's output at 53-bit precision, so the test cannot drift from it.
//
// Run:  make fpfmad-directed
//
// The cases mirror the single-precision list: fusion, ties in five rounding
// modes, subnormal operands and results, cancellation, overflow, and the
// specials.

module fpfmad_directed;
  logic [63:0] src1, src2, src3; logic [2:0] rm; logic [5:0] dest_tag;
  logic negate_product, subtract_addend, valid_in;
  logic [63:0] result; logic [5:0] tag_out; logic [4:0] exc; logic valid_out;
  logic clock = 0, reset = 0;

  FPFMAD dut (.src1(src1), .src2(src2), .src3(src3), .rm(rm), .dest_tag(dest_tag),
              .negate_product(negate_product), .subtract_addend(subtract_addend),
              .valid_in(valid_in), .result(result), .tag_out(tag_out), .exc(exc),
              .valid_out(valid_out), .clock(clock), .reset(reset), .zero(1'b0));

  always #5 clock = ~clock;

  int errors = 0;

  task run(input [8*22-1:0] name, input [63:0] a, input [63:0] b, input [63:0] c,
           input [2:0] rmode, input neg, input sub,
           input [63:0] want, input [4:0] want_exc);
    int guard;
    src1 = a; src2 = b; src3 = c; rm = rmode; dest_tag = 6'd0;
    negate_product = neg; subtract_addend = sub; valid_in = 1'b1;
    @(posedge clock);
    valid_in = 1'b0;
    guard = 0;
    while (!valid_out && guard < 30) begin
      @(posedge clock);
      guard++;
    end
    if (result !== want || exc !== want_exc) begin
      errors++;
      $display("FAIL %-22s rm=%b %016x * %016x + %016x -> %016x exc=%b, expected %016x exc=%b",
               name, rmode, a, b, c, result, exc, want, want_exc);
    end else begin
      $display("ok   %-22s rm=%b -> %016x exc=%b", name, rmode, result, exc);
    end
    @(posedge clock);
  endtask

  initial begin
    reset = 1; repeat (3) @(posedge clock); reset = 0; @(posedge clock);

    run("fusion a*b-1          ", 64'h3FF0000000000001, 64'h3FEFFFFFFFFFFFFF, 64'hBFF0000000000000, 0, 0, 0, 64'h3C9FFFFFFFFFFFFE, 5'b00000);
    run("fusion fmsub          ", 64'h3FF0000000000001, 64'h3FEFFFFFFFFFFFFF, 64'hBFF0000000000000, 0, 0, 1, 64'h4000000000000000, 5'b00001);
    run("fusion fnmadd         ", 64'h3FF0000000000001, 64'h3FEFFFFFFFFFFFFF, 64'hBFF0000000000000, 0, 1, 0, 64'hC000000000000000, 5'b00001);
    run("fusion fnmsub         ", 64'h3FF0000000000001, 64'h3FEFFFFFFFFFFFFF, 64'hBFF0000000000000, 0, 1, 1, 64'hBC9FFFFFFFFFFFFE, 5'b00000);
    run("0*inf+1 invalid       ", 64'h0000000000000000, 64'h7FF0000000000000, 64'h3FF0000000000000, 0, 0, 0, 64'h7FF8000000000000, 5'b10000);
    run("inf*1-inf invalid     ", 64'h7FF0000000000000, 64'h3FF0000000000000, 64'hFFF0000000000000, 0, 0, 0, 64'h7FF8000000000000, 5'b10000);
    run("qnan+1                ", 64'h7FF8000000000000, 64'h3FF0000000000000, 64'h3FF0000000000000, 0, 0, 0, 64'h7FF8000000000000, 5'b00000);
    run("snan*1+0              ", 64'h7FF8000000000001, 64'h3FF0000000000000, 64'h0000000000000000, 0, 0, 0, 64'h7FF8000000000000, 5'b00000);
    run("1*1-2^-60 RTZ         ", 64'h3FF0000000000000, 64'h3FF0000000000000, 64'hBC30000000000000, 1, 0, 0, 64'h3FEFFFFFFFFFFFFF, 5'b00001);
    run("1*1-2^-60 RDN         ", 64'h3FF0000000000000, 64'h3FF0000000000000, 64'hBC30000000000000, 2, 0, 0, 64'h3FEFFFFFFFFFFFFF, 5'b00001);
    run("1*1-2^-60 RNE         ", 64'h3FF0000000000000, 64'h3FF0000000000000, 64'hBC30000000000000, 0, 0, 0, 64'h3FF0000000000000, 5'b00001);
    run("tie +2^-53 RNE        ", 64'h3FF0000000000000, 64'h3FF0000000000000, 64'h3CA0000000000000, 0, 0, 0, 64'h3FF0000000000000, 5'b00001);
    run("tie +2^-53 RUP        ", 64'h3FF0000000000000, 64'h3FF0000000000000, 64'h3CA0000000000000, 3, 0, 0, 64'h3FF0000000000001, 5'b00001);
    run("tie +2^-53 RTZ        ", 64'h3FF0000000000000, 64'h3FF0000000000000, 64'h3CA0000000000000, 1, 0, 0, 64'h3FF0000000000000, 5'b00001);
    run("tie +2^-53 RMM        ", 64'h3FF0000000000000, 64'h3FF0000000000000, 64'h3CA0000000000000, 4, 0, 0, 64'h3FF0000000000001, 5'b00001);
    run("minsub*1+0            ", 64'h0000000000000001, 64'h3FF0000000000000, 64'h0000000000000000, 0, 0, 0, 64'h0000000000000001, 5'b00000);
    run("minsub*0.5+0          ", 64'h0000000000000001, 64'h3FE0000000000000, 64'h0000000000000000, 0, 0, 0, 64'h0000000000000000, 5'b00011);
    run("1*1+(-0) RNE          ", 64'h3FF0000000000000, 64'h3FF0000000000000, 64'h8000000000000000, 0, 0, 0, 64'h3FF0000000000000, 5'b00000);
    run("1*1+(-0) RDN          ", 64'h3FF0000000000000, 64'h3FF0000000000000, 64'h8000000000000000, 2, 0, 0, 64'h3FF0000000000000, 5'b00000);
    run("max*2+0 overflow      ", 64'hBFDFFFFFFFFFFFFF, 64'h4000000000000000, 64'h0000000000000000, 0, 0, 0, 64'hBFEFFFFFFFFFFFFF, 5'b00000);
    run("inf*1+0               ", 64'h7FF0000000000000, 64'h3FF0000000000000, 64'h0000000000000000, 0, 0, 0, 64'h7FF0000000000000, 5'b00000);
    run("1*1+inf               ", 64'h3FF0000000000000, 64'h3FF0000000000000, 64'h7FF0000000000000, 0, 0, 0, 64'h7FF0000000000000, 5'b00000);
    run("1*1-1 cancel RNE      ", 64'h3FF0000000000000, 64'h3FF0000000000000, 64'hBFF0000000000000, 0, 0, 0, 64'h0000000000000000, 5'b00000);
    run("1*1-1 cancel RDN      ", 64'h3FF0000000000000, 64'h3FF0000000000000, 64'hBFF0000000000000, 2, 0, 0, 64'h8000000000000000, 5'b00000);
    run("3*0.1 RNE             ", 64'h4008000000000000, 64'h3FB9999999999999, 64'h0000000000000000, 0, 0, 0, 64'h3FD3333333333333, 5'b00001);
    run("1.5*1.5-2.25 exact    ", 64'h3FF8000000000000, 64'h3FF8000000000000, 64'hC002000000000000, 0, 0, 0, 64'h0000000000000000, 5'b00000);
    run("1*1-2^-53 RUP         ", 64'h3FF0000000000000, 64'h3FF0000000000000, 64'hBCA0000000000000, 3, 0, 0, 64'h3FEFFFFFFFFFFFFF, 5'b00000);
    run("tie*3 RNE             ", 64'h3FF8000000000000, 64'h4000000000000000, 64'h0000000000000000, 0, 0, 0, 64'h4008000000000000, 5'b00000);
    run("gap 1 addend big      ", 64'hBFB999999999999A, 64'h3FEFFFFFFFFFFFFF, 64'h4000000000000000, 0, 0, 1, 64'hC000CCCCCCCCCCCD, 5'b00001);
    run("gap 3 addend big      ", 64'hBFB999999999999A, 64'h3FEFFFFFFFFFFFFF, 64'h4020000000000000, 0, 0, 1, 64'hC020333333333333, 5'b00001);
    run("gap 5 addend big      ", 64'hBFB999999999999A, 64'h3FEFFFFFFFFFFFFF, 64'h4040000000000000, 0, 0, 1, 64'hC0400CCCCCCCCCCD, 5'b00001);
    run("gap 7 addend big      ", 64'hBFB999999999999A, 64'h3FEFFFFFFFFFFFFF, 64'h4060000000000000, 0, 0, 1, 64'hC060033333333333, 5'b00001);
    run("addend>>product fmsub ", 64'hBFB999999999999A, 64'h3FEFFFFFFFFFFFFF, 64'h4000000000000000, 0, 0, 1, 64'hC000CCCCCCCCCCCD, 5'b00001);

    if (errors == 0) $display("PASS: all %0d checks agree with IEEE 754 / RISC-V", 33);
    else $display("FAIL: %0d of %0d checks disagree with IEEE 754 / RISC-V", errors, 33);
    $finish;
  end
endmodule
